from pandas.core.arrays._mixins import (

def take(
    self,
    indices: TakeIndexer,
    *,
    allow_fill: bool = False,
    fill_value: Any = None,
    axis: AxisInt = 0,
) -> Self:
    if allow_fill:
        fill_value = self._validate_scalar(fill_value)

    new_data = take(
        self._ndarray,
        indices,
        allow_fill=allow_fill,
        fill_value=fill_value,
        axis=axis,
    )
    return self._from_backing_data(new_data)

